window.__QUIZ_CHUNKS__.A2 = {"A2":{"vocab":[{"id":"q-vocab-a2-0001","level":"A2","skill":"vocab","prompt":"「il fait un temps de chien」的意思是：","options":["天气非常糟糕","天气很好","有雾","要下雪"],"answer":"天气非常糟糕","explain":"un temps de chien 是习语，指天气糟透了；天气好是 il fait beau，有雾是 il y a du brouillard，下雪是 il neige。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-a2-0002","level":"A2","skill":"vocab","prompt":"「une averse」的意思是：","options":["阵雨","干旱","彩虹","微风"],"answer":"阵雨","explain":"averse 是短时阵雨；干旱是 sécheresse，彩虹是 arc-en-ciel，微风是 brise。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-a2-0003","level":"A2","skill":"vocab","prompt":"「le brouillard」的意思是：","options":["雾","冰雹","霜","雷"],"answer":"雾","explain":"brouillard 是雾；冰雹是 grêle，霜是 gelée，雷是 tonnerre。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-a2-0004","level":"A2","skill":"vocab","prompt":"「Il y a du vent.」的意思是：","options":["有风","下雨","出太阳","很闷热"],"answer":"有风","explain":"vent 是风（il y a du vent 起风了）；下雨是 il pleut，出太阳是 il y a du soleil，闷热是 il fait lourd。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-a2-0005","level":"A2","skill":"vocab","prompt":"「la marée」的意思是：","options":["潮汐","海浪","海底","沙滩"],"answer":"潮汐","explain":"marée 指潮汐（marée haute 涨潮、marée basse 退潮）；海浪是 vague，海底是 fond marin，沙滩是 plage。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-a2-0006","level":"A2","skill":"vocab","prompt":"「télécharger une application」的意思是：","options":["下载一个应用","卸载一个应用","安装操作系统","发短信"],"answer":"下载一个应用","explain":"télécharger 是下载；卸载是 désinstaller，安装系统是 installer un système，发短信是 envoyer un SMS。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-a2-0007","level":"A2","skill":"vocab","prompt":"「un mot de passe」的意思是：","options":["密码","用户名","验证码","账号"],"answer":"密码","explain":"mot de passe 是密码；用户名是 nom d'utilisateur，验证码是 code de vérification，账号是 compte。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-a2-0008","level":"A2","skill":"vocab","prompt":"「créer un compte」的意思是：","options":["创建账号","注销账号","重置密码","登录"],"answer":"创建账号","explain":"créer un compte 是注册新账号；注销账号是 supprimer un compte，重置密码是 réinitialiser le mot de passe，登录是 se connecter。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-a2-0009","level":"A2","skill":"vocab","prompt":"「mettre à jour」的意思是：","options":["更新","关机","备份","删除"],"answer":"更新","explain":"mettre à jour 是更新（名词形式 une mise à jour）；关机是 éteindre，备份是 sauvegarder，删除是 supprimer。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-a2-0010","level":"A2","skill":"vocab","prompt":"「le réseau」的意思是：","options":["网络","键盘","屏幕","电池"],"answer":"网络","explain":"réseau 是网络（réseau social 社交网络）；键盘是 clavier，屏幕是 écran，电池是 batterie。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-a2-0011","level":"A2","skill":"vocab","prompt":"「les informations (les infos)」的意思是：","options":["新闻（节目）","广告","电视剧","杂志"],"answer":"新闻（节目）","explain":"les informations 指新闻节目或新闻；广告是 publicité，电视剧是 série，杂志是 magazine。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-a2-0012","level":"A2","skill":"vocab","prompt":"「une émission de radio」的意思是：","options":["电台节目","电影票","报纸专栏","演唱会"],"answer":"电台节目","explain":"émission 是广播或电视节目；电影票是 billet de cinéma，专栏是 chronique，演唱会是 concert。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-a2-0013","level":"A2","skill":"vocab","prompt":"「le petit écran」指的是：","options":["电视","手机屏幕","电影院","电脑显示器"],"answer":"电视","explain":"le petit écran 是电视的比喻说法（对应 le grand écran 电影大银幕）；手机屏幕是 écran de téléphone，电影院是 cinéma。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-a2-0014","level":"A2","skill":"vocab","prompt":"「sortir au cinéma」的意思是：","options":["去看电影","从电影院出来","拍电影","关掉电视"],"answer":"去看电影","explain":"sortir au cinéma 是外出看电影；从电影院出来是 sortir du cinéma，拍电影是 tourner un film，关电视是 éteindre la télé。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-a2-0015","level":"A2","skill":"vocab","prompt":"「faire de la natation」的意思是：","options":["游泳（作为运动）","划船","钓鱼","潜水"],"answer":"游泳（作为运动）","explain":"natation 是游泳这项运动（nager 是动作）；划船是 faire du bateau，钓鱼是 pêcher，潜水是 plonger。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-a2-0016","level":"A2","skill":"vocab","prompt":"「un match nul」的意思是：","options":["平局","主场比赛","加时赛","决赛"],"answer":"平局","explain":"match nul 是平局；主场比赛是 match à domicile，加时赛是 prolongation，决赛是 finale。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-a2-0017","level":"A2","skill":"vocab","prompt":"「s'entraîner」的意思是：","options":["训练","报名","当裁判","加油助威"],"answer":"训练","explain":"s'entraîner 是训练（entraîneur 是教练）；报名是 s'inscrire，裁判是 arbitre，加油助威是 encourager。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-a2-0018","level":"A2","skill":"vocab","prompt":"「le terrain de football」的意思是：","options":["足球场","足球运动员","足球鞋","足球比赛"],"answer":"足球场","explain":"terrain 指场地（terrain de sport）；运动员是 joueur，球鞋是 chaussures de sport，比赛是 match。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-a2-0019","level":"A2","skill":"vocab","prompt":"「être déçu」的意思是：","options":["失望","满意","惊讶","生气"],"answer":"失望","explain":"être déçu 是失望（décevant 令人失望的）；满意是 satisfait，惊讶是 surpris，生气是 en colère。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-a2-0020","level":"A2","skill":"vocab","prompt":"「avoir peur de qch」的意思是：","options":["害怕某物","担心别人","讨厌某物","羡慕某人"],"answer":"害怕某物","explain":"avoir peur de 是害怕；担心别人是 s'inquiéter pour qqn，讨厌是 détester，羡慕是 envier。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-a2-0021","level":"A2","skill":"vocab","prompt":"「Il est de bonne humeur.」的意思是：","options":["他心情好","他有幽默感","他脾气差","他很有礼貌"],"answer":"他心情好","explain":"être de bonne humeur 指心情好（对应的 mauvaise humeur 是心情差）；有幽默感是 avoir de l'humour，脾气差是 être colérique，有礼貌是 être poli。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-a2-0022","level":"A2","skill":"vocab","prompt":"「Je suis désolé.」的意思是：","options":["我很抱歉","我很孤独","我很失望","我很着急"],"answer":"我很抱歉","explain":"désolé 是抱歉、遗憾；孤独是 seul，失望是 déçu，着急是 pressé。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-a2-0023","level":"A2","skill":"vocab","prompt":"「le chômage」的意思是：","options":["失业","罢工","移民","贫穷"],"answer":"失业","explain":"chômage 是失业现象，失业者是 chômeur；罢工是 grève，移民是 immigration，贫穷是 pauvreté。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-a2-0024","level":"A2","skill":"vocab","prompt":"「l'égalité entre les femmes et les hommes」的意思是：","options":["男女平等","男女差异","女性就业","家庭分工"],"answer":"男女平等","explain":"égalité 是平等；差异是 différence，就业是 emploi，分工是 répartition des tâches。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-a2-0025","level":"A2","skill":"vocab","prompt":"「une association caritative」的意思是：","options":["慈善协会","工会","政党","保险公司"],"answer":"慈善协会","explain":"association caritative 是慈善组织；工会是 syndicat，政党是 parti politique，保险公司是 compagnie d'assurance。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-a2-0026","level":"A2","skill":"vocab","prompt":"「les sans-abri」的意思是：","options":["无家可归者","无国籍者","素食者","失业者"],"answer":"无家可归者","explain":"sans-abri 指没有住所的人（单复数同形）；无国籍者是 apatride，素食者是 végétarien，失业者是 chômeur。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-a2-0027","level":"A2","skill":"vocab","prompt":"「le réchauffement climatique」的意思是：","options":["气候变暖","天气预报","空气污染","自然灾害"],"answer":"气候变暖","explain":"réchauffement climatique 是气候变暖；天气预报是 météo，空气污染是 pollution de l'air，自然灾害是 catastrophe naturelle。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-a2-0028","level":"A2","skill":"vocab","prompt":"「trier les déchets」的意思是：","options":["垃圾分类","回收旧衣","减少用水","焚烧垃圾"],"answer":"垃圾分类","explain":"trier les déchets 是给垃圾分类（la poubelle jaune 是可回收物桶）；回收旧衣是 recycler les vêtements，节水是 économiser l'eau，焚烧是 incinérer。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-a2-0029","level":"A2","skill":"vocab","prompt":"「l'empreinte carbone」的意思是：","options":["碳足迹","碳排放税","温室气体","石油储量"],"answer":"碳足迹","explain":"empreinte carbone 是个人或活动留下的碳排放总量；碳税是 taxe carbone，温室气体是 gaz à effet de serre，石油储量是 réserves de pétrole。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-a2-0030","level":"A2","skill":"vocab","prompt":"「une énergie renouvelable」的意思是：","options":["可再生能源","核能","化石燃料","电力网"],"answer":"可再生能源","explain":"renouvelable 是可再生的（风能 éolien、太阳能 solaire）；核能是 nucléaire，化石燃料是 énergies fossiles，电力网是 réseau électrique。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-a2-0031","level":"A2","skill":"vocab","prompt":"「le droit de vote」的意思是：","options":["选举权","法律条文","投票站","选民名单"],"answer":"选举权","explain":"droit de vote 是投票权；法律条文是 texte de loi，投票站是 bureau de vote，选民名单是 liste électorale。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-a2-0032","level":"A2","skill":"vocab","prompt":"「un projet de loi」的意思是：","options":["法律草案","法院判决","宪法修正案","竞选纲领"],"answer":"法律草案","explain":"projet de loi 是提交议会审议的法案；判决是 jugement，宪法修正案是 révision constitutionnelle，竞选纲领是 programme électoral。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-a2-0033","level":"A2","skill":"vocab","prompt":"「être condamné à une amende」的意思是：","options":["被判罚款","被无罪释放","被起诉","被拘留"],"answer":"被判罚款","explain":"condamner à une amende 是判处罚金；无罪释放是 être acquitté，被起诉是 être poursuivi，被拘留是 être placé en garde à vue。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-a2-0034","level":"A2","skill":"vocab","prompt":"「la liberté d'expression」的意思是：","options":["言论自由","行动自由","新闻审查","出版许可"],"answer":"言论自由","explain":"liberté d'expression 是表达自由；行动自由是 liberté de mouvement，新闻审查是 censure，出版许可是 autorisation de publication。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-a2-0035","level":"A2","skill":"vocab","prompt":"「le pouvoir d'achat」的意思是：","options":["购买力","增值税","通货膨胀","银行利率"],"answer":"购买力","explain":"pouvoir d'achat 是购买力；增值税是 TVA，通货膨胀是 inflation，银行利率是 taux d'intérêt。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-a2-0036","level":"A2","skill":"vocab","prompt":"「faire des économies」的意思是：","options":["存钱、省钱","做经济研究","贷款","投资股票"],"answer":"存钱、省钱","explain":"faire des économies 指攒钱或省钱；做经济研究是 faire des études d'économie，贷款是 emprunter，投资股票是 investir en bourse。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-a2-0037","level":"A2","skill":"vocab","prompt":"「une entreprise qui embauche」的意思是：","options":["正在招人的企业","正在裁员的企业","刚成立的企业","上市公司"],"answer":"正在招人的企业","explain":"embaucher 是招聘；裁员是 licencier，刚成立是 récemment créée，上市公司是 société cotée en bourse。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-a2-0038","level":"A2","skill":"vocab","prompt":"「le chiffre d'affaires」的意思是：","options":["营业额","净利润","员工人数","市场份额"],"answer":"营业额","explain":"chiffre d'affaires（缩写 CA）是营业额；净利润是 bénéfice net，员工人数是 effectif，市场份额是 part de marché。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-a2-0039","level":"A2","skill":"vocab","prompt":"「une exposition de peinture」的意思是：","options":["画展","音乐会","话剧","电影节"],"answer":"画展","explain":"exposition 是展览；音乐会是 concert，话剧是 pièce de théâtre，电影节是 festival du film。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-a2-0040","level":"A2","skill":"vocab","prompt":"「le patrimoine culturel」的意思是：","options":["文化遗产","文化冲突","文物保护法","博物馆门票"],"answer":"文化遗产","explain":"patrimoine culturel 是文化遗产；文化冲突是 choc culturel，文物保护法是 loi sur la protection du patrimoine，门票是 billet d'entrée。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-a2-0041","level":"A2","skill":"vocab","prompt":"「un roman policier」的意思是：","options":["侦探小说","历史小说","诗集","自传"],"answer":"侦探小说","explain":"roman policier 是侦探、犯罪小说；历史小说是 roman historique，诗集是 recueil de poèmes，自传是 autobiographie。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-a2-0042","level":"A2","skill":"vocab","prompt":"「mettre en scène une pièce」的意思是：","options":["排演一部戏","写一部戏","看一部戏","翻译一部戏"],"answer":"排演一部戏","explain":"mettre en scène 是导演、搬上舞台（le metteur en scène 导演）；写是 écrire，看是 voir，翻译是 traduire。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-a2-0043","level":"A2","skill":"vocab","prompt":"「la plupart des gens」的意思是：","options":["大多数人","少数人","所有人","有些人"],"answer":"大多数人","explain":"la plupart de + 复数名词表「大多数」，动词用复数；少数人是 une minorité，所有人是 tout le monde，有些人是 certains。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-a2-0044","level":"A2","skill":"vocab","prompt":"「par conséquent」的意思是：","options":["因此","然而","例如","相反"],"answer":"因此","explain":"par conséquent 表结果（因此）；然而、相反是 en revanche，例如是 par exemple。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-a2-0045","level":"A2","skill":"vocab","prompt":"「un avantage」的意思是：","options":["优点","缺点","目标","结果"],"answer":"优点","explain":"avantage 是优势、好处；缺点是 inconvénient，目标是 objectif，结果是 résultat。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-a2-0046","level":"A2","skill":"vocab","prompt":"「de plus en plus」的意思是：","options":["越来越","越来越少","立刻","偶尔"],"answer":"越来越","explain":"de plus en plus 表递增（越来越少是 de moins en moins）；立刻是 tout de suite，偶尔是 de temps en temps。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-a2-0047","level":"A2","skill":"vocab","prompt":"「se rendre compte de qch」的意思是：","options":["意识到某事","去某处报到","归还某物","依靠某人"],"answer":"意识到某事","explain":"se rendre compte de 是觉察、意识到；报到是 se présenter，归还是 rendre，依靠是 compter sur。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"},{"id":"q-vocab-a2-0048","level":"A2","skill":"vocab","prompt":"「mettre en place un système」的意思是：","options":["建立一套制度","拆除一套制度","讨论一套制度","违反一套制度"],"answer":"建立一套制度","explain":"mettre en place 是设立、落实；拆除是 supprimer，讨论是 discuter，违反是 violer。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"},{"id":"q-vocab-a2-0049","level":"A2","skill":"vocab","prompt":"「avoir besoin de qch」的意思是：","options":["需要某物","缺少某物","拥有某物","拒绝某物"],"answer":"需要某物","explain":"avoir besoin de 是需要；缺少是 manquer de，拥有是 posséder，拒绝是 refuser。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"},{"id":"q-vocab-a2-0050","level":"A2","skill":"vocab","prompt":"「faire attention à qch」的意思是：","options":["注意某事","照顾某人","喜欢某事","打扰某人"],"answer":"注意某事","explain":"faire attention à 是当心、注意；照顾是 s'occuper de，喜欢是 aimer，打扰是 déranger。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"}],"grammar":[{"id":"q-gram-a2-0001","level":"A2","skill":"grammar","prompt":"un journal → des ___","options":["journaux","journals","journales","journal"],"answer":"journaux","explain":"-al 结尾的名词复数变 -aux：journal → journaux；journals 是照英语加 -s，journales 是臆造形式，journal 是单数。","source":"语法点 · 名词复数（le pluriel des noms） · grammar-a1a2.html#noun-pluriel"},{"id":"q-gram-a2-0002","level":"A2","skill":"grammar","prompt":"un œil → des ___","options":["yeux","œils","oeils","œil"],"answer":"yeux","explain":"œil 的复数是不规则形式 yeux；œils 只出现在少数复合词里（如 des œils-de-bœuf），oeils 拼写不合规范，œil 是单数。","source":"语法点 · 名词复数（le pluriel des noms） · grammar-a1a2.html#noun-pluriel"},{"id":"q-gram-a2-0003","level":"A2","skill":"grammar","prompt":"un travail → des ___","options":["travaux","travails","travailes","travail"],"answer":"travaux","explain":"travail 属 -ail 的例外，复数变 travaux（同类还有 un vitrail → des vitraux）；travails 只在极个别技术语境使用，日常一律 travaux。","source":"语法点 · 名词复数（le pluriel des noms） · grammar-a1a2.html#noun-pluriel"},{"id":"q-gram-a2-0004","level":"A2","skill":"grammar","prompt":"Voici un ___ roman.","options":["nouveau","nouvel","roman nouveau","nouvelle"],"answer":"nouveau","explain":"nouveau 属 BAGS 类前置形容词，要放在名词前；roman 以辅音 r 开头，所以用 nouveau（nouvel 只用于元音或哑音 h 前），roman nouveau 后置语序不合规范，nouvelle 是阴性。","source":"语法点 · 形容词的位置（la place de l'adjectif） · grammar-a1a2.html#adj-place"},{"id":"q-gram-a2-0005","level":"A2","skill":"grammar","prompt":"un homme grand 的意思是：","options":["一个身材高大的男人","一个伟人","一个老男人","一个很和蔼的男人"],"answer":"一个身材高大的男人","explain":"形容词后置时取本义「身材高大」；前置 un grand homme 才表示「伟人」，所以「伟人」对应的语序不对；老男人是 un vieil homme，和蔼与 grande 无关。","source":"语法点 · 形容词的位置（la place de l'adjectif） · grammar-a1a2.html#adj-place"},{"id":"q-gram-a2-0006","level":"A2","skill":"grammar","prompt":"选出语序与配合都正确的句子（一辆法国车）：","options":["une voiture française","une française voiture","une voiture français","une voiture françaises"],"answer":"une voiture française","explain":"表国籍、颜色的形容词一般后置，并与阴性单数名词配合加 -e：une voiture française；française voiture 前置语序错，français 缺配合，françaises 是复数形式。","source":"语法点 · 形容词的位置（la place de l'adjectif） · grammar-a1a2.html#adj-place"},{"id":"q-gram-a2-0007","level":"A2","skill":"grammar","prompt":"un ___ homme","options":["bel","beau","belle","beaux"],"answer":"bel","explain":"beau 在元音或哑音 h 开头的阳性名词前变 bel：un bel homme；beau 不能用在元音前，belle 是阴性，beaux 是阳性复数。","source":"语法点 · beau / nouveau / vieux 特殊形式（les adjectifs beau, nouveau, vieux） · grammar-a1a2.html#adj-special"},{"id":"q-gram-a2-0008","level":"A2","skill":"grammar","prompt":"un ___ appartement","options":["nouvel","nouveau","nouvelle","nouveaux"],"answer":"nouvel","explain":"nouveau 在元音或哑音 h 开头的阳性单数名词前变 nouvel；appartement 以 a 开头，所以用 un nouvel appartement；nouveau 不能用在元音前，nouvelle 是阴性，nouveaux 是复数。","source":"语法点 · beau / nouveau / vieux 特殊形式（les adjectifs beau, nouveau, vieux） · grammar-a1a2.html#adj-special"},{"id":"q-gram-a2-0009","level":"A2","skill":"grammar","prompt":"un ___ arbre","options":["vieil","vieux","vieille","vieilles"],"answer":"vieil","explain":"vieux 在元音或哑音 h 开头的阳性单数名词前变 vieil：un vieil arbre；vieux 不能用于元音前，vieille / vieilles 是阴性形式。","source":"语法点 · beau / nouveau / vieux 特殊形式（les adjectifs beau, nouveau, vieux） · grammar-a1a2.html#adj-special"},{"id":"q-gram-a2-0010","level":"A2","skill":"grammar","prompt":"___ étudiant doit apporter son dictionnaire.","options":["Chaque","Chacun","Tous","Quelques"],"answer":"Chaque","explain":"chaque 只修饰单数名词，而且名词前不再加冠词；chacun 是代词，不能直接接名词；tous 和 quelques 都要求复数名词。","source":"语法点 · 整体表达 chaque / tout / aucun（les indéfinis） · grammar-a1a2.html#quant-autres"},{"id":"q-gram-a2-0011","level":"A2","skill":"grammar","prompt":"Elle n'a ___ ami à Paris.","options":["aucun","pas aucun","quelque","chaque"],"answer":"aucun","explain":"aucun 与 ne 连用表示「一个也没有」：n'a aucun ami；pas aucun 重复否定且语序错误，quelque 是肯定含义，chaque 只修饰单数且不表否定。","source":"语法点 · 整体表达 chaque / tout / aucun（les indéfinis） · grammar-a1a2.html#quant-autres"},{"id":"q-gram-a2-0012","level":"A2","skill":"grammar","prompt":"___ mes amis sont venus à la fête.","options":["Tous","Tout","Toute","Chaque"],"answer":"Tous","explain":"阳性复数名词前用 tous：tous mes amis；tout 是单数形式，toute 是阴性单数，chaque 只能修饰单数名词。","source":"语法点 · 整体表达 chaque / tout / aucun（les indéfinis） · grammar-a1a2.html#quant-autres"},{"id":"q-gram-a2-0013","level":"A2","skill":"grammar","prompt":"Il habite au ___ étage.（第 9 层）","options":["neuvième","neufième","quatre-vingt-dixième","neuve"],"answer":"neuvième","explain":"neuf 的序数词是 neuvième（f 变 v 并加 -ième）；neufième 拼写错误，quatre-vingt-dixième 是第 90，neuve 是形容词阴性。","source":"语法点 · 序数词（les nombres ordinaux） · grammar-a1a2.html#num-ord"},{"id":"q-gram-a2-0014","level":"A2","skill":"grammar","prompt":"C'est la ___ fois que je viens ici.","options":["deuxième","deux","deuxièmement","secondes"],"answer":"deuxième","explain":"序数词 deuxième 表示「第二次」；deux 是基数词，不能限定 fois，deuxièmement 是副词「第二点」，secondes 是形容词阴性复数。","source":"语法点 · 序数词（les nombres ordinaux） · grammar-a1a2.html#num-ord"},{"id":"q-gram-a2-0015","level":"A2","skill":"grammar","prompt":"Tu vas à la bibliothèque ? — Oui, j'___ vais.","options":["y","en","le","la"],"answer":"y","explain":"y 替代 à + 地点：j'y vais；en 替代 de + 名词或数量，le 和 la 是直接宾语代词，都不能替代地点状语。","source":"语法点 · 副代词 y 与 en（les pronoms y et en） · grammar-a1a2.html#pro-y-en"},{"id":"q-gram-a2-0016","level":"A2","skill":"grammar","prompt":"Tu veux du café ? — Oui, j'___ veux bien.","options":["en","y","le","du"],"answer":"en","explain":"部分冠词 du + 名词由 en 替代，数量/冠词信息由动词承担：j'en veux；y 替代 à + 名词或地点，le 是特指性直接宾语代词，du 不能单独作代词。","source":"语法点 · 副代词 y 与 en（les pronoms y et en） · grammar-a1a2.html#pro-y-en"},{"id":"q-gram-a2-0017","level":"A2","skill":"grammar","prompt":"Il pense à son examen ? — Oui, il ___ pense souvent.","options":["y","en","le","lui"],"answer":"y","explain":"penser à qch 用 y 替代 à + 事物；en 替代 de + 事物（如 parler de），le 是直接宾语代词，lui 只替代 à + 人（penser à sa mère → penser à elle）。","source":"语法点 · 副代词 y 与 en（les pronoms y et en） · grammar-a1a2.html#pro-y-en"},{"id":"q-gram-a2-0018","level":"A2","skill":"grammar","prompt":"Elle a beaucoup de livres. — Elle ___ a beaucoup.","options":["en","y","les","leur"],"answer":"en","explain":"数量副词后的名词用 en 替代，数量词 beaucoup 要保留：elle en a beaucoup；y 替代地点或 à + 事物，les 会丢掉数量信息，leur 是间接宾语代词。","source":"语法点 · 副代词 y 与 en（les pronoms y et en） · grammar-a1a2.html#pro-y-en"},{"id":"q-gram-a2-0019","level":"A2","skill":"grammar","prompt":"Ils ___ leurs livres à la fin du cours.（vendre）","options":["vendent","vendons","vendez","vends"],"answer":"vendent","explain":"-re 动词 ils 形式以 -ent 结尾并保留词干 d：vendent；vendons 是 nous 形式，vendez 是 vous 形式，vends 是 je / tu 形式。","source":"语法点 · -re 动词现在时（présent des verbes en -re） · grammar-a1a2.html#pres-re"},{"id":"q-gram-a2-0020","level":"A2","skill":"grammar","prompt":"Elle ___ le bus depuis vingt minutes.（attendre）","options":["attend","attends","attendez","attendent"],"answer":"attend","explain":"第三人称单数是 -re 动词唯一不加词尾的形式：elle attend（不写 -t）；attends 是 je / tu 形式，attendez 是 vous 形式，attendent 是 ils 形式。","source":"语法点 · -re 动词现在时（présent des verbes en -re） · grammar-a1a2.html#pres-re"},{"id":"q-gram-a2-0021","level":"A2","skill":"grammar","prompt":"Je ___ à sept heures tous les matins.（se lever）","options":["me lève","me lèves","se lève","me lever"],"answer":"me lève","explain":"主语 je 配自反代词 me，lever 的 je 形式是 lève：je me lève；me lèves 动词人称错，se lève 是 il / elle 形式，me lever 是原形。","source":"语法点 · 代词式动词（les verbes pronominaux） · grammar-a1a2.html#verbes-pronominaux"},{"id":"q-gram-a2-0022","level":"A2","skill":"grammar","prompt":"Nous ___ à huit heures.（se réveiller）","options":["nous réveillons","se réveillons","nous réveillez","nous réveiller"],"answer":"nous réveillons","explain":"nous 配自反代词 nous，动词 réveillons：nous nous réveillons；se réveillons 自反代词人称错，nous réveillez 动词人称错，nous réveiller 是原形。","source":"语法点 · 代词式动词（les verbes pronominaux） · grammar-a1a2.html#verbes-pronominaux"},{"id":"q-gram-a2-0023","level":"A2","skill":"grammar","prompt":"Hier, elle ___ à dix heures.（se coucher，复合过去时）","options":["s'est couchée","s'est couché","a se couché","s'a couchée"],"answer":"s'est couchée","explain":"代词式动词复合过去时一律用 être，过去分词与主语 elle 配合加 -e：s'est couchée；s'est couché 缺配合，a se couché 助动词错，s'a couchée 助动词与自反代词位置都错。","source":"语法点 · 代词式动词（les verbes pronominaux） · grammar-a1a2.html#verbes-pronominaux"},{"id":"q-gram-a2-0024","level":"A2","skill":"grammar","prompt":"Ils ___ Paul et Marie.（s'appeler）","options":["s'appellent","s'appelent","se appellent","s'appelle"],"answer":"s'appellent","explain":"s'appeler 的 ils 形式双写 l：s'appellent；s'appelent 漏写双辅音，se appellent 未省音（应为 s'），s'appelle 是单数形式。","source":"语法点 · 代词式动词（les verbes pronominaux） · grammar-a1a2.html#verbes-pronominaux"},{"id":"q-gram-a2-0025","level":"A2","skill":"grammar","prompt":"Il ___ de rentrer à la maison.","options":["vient","va","venir","venait"],"answer":"vient","explain":"最近过去时是 venir de + 不定式，il 用 vient：il vient de rentrer；va 构成最近将来时，venir 是原形（缺变位），venait 是未完成过去时。","source":"语法点 · 最近过去时（le passé récent） · grammar-a1a2.html#passe-recent"},{"id":"q-gram-a2-0026","level":"A2","skill":"grammar","prompt":"Je ___ de finir mes devoirs.","options":["viens","vient","venais","vais"],"answer":"viens","explain":"je 对应 viens：je viens de finir；vient 是 il / elle 形式，venais 是未完成过去时，vais 是 aller（表将来）。","source":"语法点 · 最近过去时（le passé récent） · grammar-a1a2.html#passe-recent"},{"id":"q-gram-a2-0027","level":"A2","skill":"grammar","prompt":"Nous ___ de déjeuner au restaurant.","options":["venons","venez","viennent","venions"],"answer":"venons","explain":"nous 对应 venons：nous venons de déjeuner；venez 是 vous 形式，viennent 是 ils 形式，venions 是未完成过去时。","source":"语法点 · 最近过去时（le passé récent） · grammar-a1a2.html#passe-recent"},{"id":"q-gram-a2-0028","level":"A2","skill":"grammar","prompt":"Hier, Paul ___ au cinéma avec ses amis.","options":["est allé","a allé","est allée","est allés"],"answer":"est allé","explain":"aller 属 DR MRS VANDERTRAMP，复合过去时用 être 且过去分词与阳性单数主语 Paul 一致（不加 -e）：est allé；a allé 助动词错，est allée 是阴性，est allés 是复数。","source":"语法点 · 复合过去时（le passé composé） · grammar-a1a2.html#passe-compose"},{"id":"q-gram-a2-0029","level":"A2","skill":"grammar","prompt":"Elles ___ à la fête hier soir.（partir）","options":["sont parties","ont parties","sont parti","sont partis"],"answer":"sont parties","explain":"partir 用 être 作助动词，过去分词与阴性复数主语 elles 配合加 -es：sont parties；ont parties 助动词错，sont parti 缺配合，sont partis 是阳性复数。","source":"语法点 · 复合过去时（le passé composé） · grammar-a1a2.html#passe-compose"},{"id":"q-gram-a2-0030","level":"A2","skill":"grammar","prompt":"J'ai ___ une pomme ce matin.（manger）","options":["mangé","mangée","mangés","manger"],"answer":"mangé","explain":"manger 用 avoir，过去分词不与主语配合，也不与动词后的宾语配合：j'ai mangé une pomme；mangée / mangés 都是错误配合，manger 是原形。","source":"语法点 · 复合过去时（le passé composé） · grammar-a1a2.html#passe-compose"},{"id":"q-gram-a2-0031","level":"A2","skill":"grammar","prompt":"Les livres que j'ai ___ sont très intéressants.（lire）","options":["lus","lu","lues","lire"],"answer":"lus","explain":"avoir 型动词的过去分词要与前置直接宾语配合，les livres 是阳性复数，所以是 lus；lu 缺配合，lues 是阴性复数，lire 是原形。","source":"语法点 · 复合过去时（le passé composé） · grammar-a1a2.html#passe-compose"},{"id":"q-gram-a2-0032","level":"A2","skill":"grammar","prompt":"Ma sœur ___ née en 2001.","options":["est","a","a été","était"],"answer":"est","explain":"naître 用 être 作助动词：est née；a 助动词错，a été née 把 être 再复合一次造成赘余，était 是未完成过去时，与确切年份的表达不符。","source":"语法点 · 复合过去时（le passé composé） · grammar-a1a2.html#passe-compose"},{"id":"q-gram-a2-0033","level":"A2","skill":"grammar","prompt":"Quand j'étais petit, je ___ au football tous les samedis.（jouer）","options":["jouais","joue","ai joué","jouerais"],"answer":"jouais","explain":"表过去的习惯用未完成过去时，je 的词尾是 -ais：je jouais；joue 是现在时，ai joué 表一次性事件，jouerais 是条件式。","source":"语法点 · 未完成过去时（l'imparfait） · grammar-a1a2.html#imparfait"},{"id":"q-gram-a2-0034","level":"A2","skill":"grammar","prompt":"Il ___ quand je suis entré dans la salle.（pleuvoir）","options":["pleuvait","pleut","a plu","pleuvra"],"answer":"pleuvait","explain":"未完成过去时用来描写正在进行的背景：il pleuvait；pleut 是现在时，a plu 把天气当成一次性事件，与「我进门时正在下雨」的背景描写不符，pleuvra 是将来时。","source":"语法点 · 未完成过去时（l'imparfait） · grammar-a1a2.html#imparfait"},{"id":"q-gram-a2-0035","level":"A2","skill":"grammar","prompt":"Nous ___ souvent à la mer en été.（aller）","options":["allions","allons","sommes allés","irons"],"answer":"allions","explain":"souvent 表示过去反复的习惯，用未完成过去时 allions（nous 词尾 -ions）；allons 是现在时，sommes allés 表一次完成的事件，irons 是将来时。","source":"语法点 · 未完成过去时（l'imparfait） · grammar-a1a2.html#imparfait"},{"id":"q-gram-a2-0036","level":"A2","skill":"grammar","prompt":"Quand je ___ , le téléphone a sonné.（dormir）","options":["dormais","ai dormi","dors","dormirai"],"answer":"dormais","explain":"被事件打断的持续背景用未完成过去时 dormais，事件 a sonné 用复合过去时；ai dormi 会与事件冲突，dors 是现在时，dormirai 是将来时。","source":"语法点 · 两种过去时的分工（passé composé vs imparfait） · grammar-a1a2.html#pc-imparfait"},{"id":"q-gram-a2-0037","level":"A2","skill":"grammar","prompt":"Samedi dernier, nous ___ au marché, puis nous ___ un bon déjeuner.","options":["sommes allés / avons pris","allions / prenions","allons / prenons","irons / prendrons"],"answer":"sommes allés / avons pris","explain":"puis 连接的连续事件用复合过去时推进叙事；allions / prenions 是背景描写，现在时和将来时与 samedi dernier 的时间标记冲突。","source":"语法点 · 两种过去时的分工（passé composé vs imparfait） · grammar-a1a2.html#pc-imparfait"},{"id":"q-gram-a2-0038","level":"A2","skill":"grammar","prompt":"Il ___ beau, alors nous sommes sortis.（faire）","options":["faisait","a fait","fait","fera"],"answer":"faisait","explain":"天气是场景背景，用未完成过去时 faisait；alors 引出的事件用复合过去时，所以背景不能用 a fait，fait 是现在时，fera 是将来时。","source":"语法点 · 两种过去时的分工（passé composé vs imparfait） · grammar-a1a2.html#pc-imparfait"},{"id":"q-gram-a2-0039","level":"A2","skill":"grammar","prompt":"Chaque année, ils ___ en Bretagne. Un été, ils y ___ un mois.","options":["allaient / sont restés","sont allés / restaient","vont / restent","iront / resteraient"],"answer":"allaient / sont restés","explain":"chaque année 表反复出现的习惯用未完成过去时，un été 表具体的一次用复合过去时；其余选项把两个时间标志的作用弄反，或误用现在时、将来时。","source":"语法点 · 两种过去时的分工（passé composé vs imparfait） · grammar-a1a2.html#pc-imparfait"},{"id":"q-gram-a2-0040","level":"A2","skill":"grammar","prompt":"Demain, il ___ ses grands-parents.（voir）","options":["verra","verras","vera","voit"],"answer":"verra","explain":"voir 的简单将来时词干是 verr-，je / il 形式为 verra；verras 是 tu 形式，vera 少写了一个 r，voit 是现在时。","source":"语法点 · 简单将来时（le futur simple） · grammar-a1a2.html#futur-simple"},{"id":"q-gram-a2-0041","level":"A2","skill":"grammar","prompt":"Nous ___ nos amis dimanche prochain.（inviter）","options":["inviterons","invitons","inviterions","avez invité"],"answer":"inviterons","explain":"第一组动词简单将来时＝不定式 + 词尾，nous 用 -ons：inviterons；invitons 是现在时，inviterions 是条件式，avez invité 是复合过去时且人称不符。","source":"语法点 · 简单将来时（le futur simple） · grammar-a1a2.html#futur-simple"},{"id":"q-gram-a2-0042","level":"A2","skill":"grammar","prompt":"Ils ___ bientôt la vérité.（savoir）","options":["sauront","saurons","savoiront","savent"],"answer":"sauront","explain":"savoir 的将来时词干不规则，为 saur-：ils sauront；saurons 是 nous 形式，savoiront 臆造词干，savent 是现在时。","source":"语法点 · 简单将来时（le futur simple） · grammar-a1a2.html#futur-simple"},{"id":"q-gram-a2-0043","level":"A2","skill":"grammar","prompt":"___ -vous m'aider, s'il vous plaît ?","options":["Pourriez","Pouvez","Pourrez","Pouviez"],"answer":"Pourriez","explain":"条件式现在时表委婉礼貌的请求：Pourriez-vous；Pouvez 是直陈式现在时（语气较直接），Pourrez 是将来时，Pouviez 是未完成过去时。","source":"语法点 · 简单条件式（le conditionnel présent） · grammar-a1a2.html#conditionnel-present"},{"id":"q-gram-a2-0044","level":"A2","skill":"grammar","prompt":"Si j'avais de l'argent, je ___ une voiture.","options":["achèterais","achète","achèterai","avais acheté"],"answer":"achèterais","explain":"si + 未完成过去时，主句用条件式现在时；achète 是现在时，achèterai 是将来时，avais acheté 是愈过去时（应配 si + 愈过去时）。","source":"语法点 · 简单条件式（le conditionnel présent） · grammar-a1a2.html#conditionnel-present"},{"id":"q-gram-a2-0045","level":"A2","skill":"grammar","prompt":"Il ___ être malade : il n'est pas venu au cours.","options":["serait","sera","est","était"],"answer":"serait","explain":"条件式现在时可表推测（「据说/可能」）：il serait malade；sera 是将来时，est 是现在时，était 是未完成过去时，都不能表达这种传闻推测语气。","source":"语法点 · 简单条件式（le conditionnel présent） · grammar-a1a2.html#conditionnel-present"},{"id":"q-gram-a2-0046","level":"A2","skill":"grammar","prompt":"Elle est ___ que sa sœur.（更高）","options":["plus grande","plus grand","meilleure","la plus grande"],"answer":"plus grande","explain":"比较级是 plus + 形容词 + que，形容词要与阴性主语配合：plus grande；plus grand 缺配合，meilleure 是 bon 的比较级（「更好」），la plus grande 是最高级而不是比较级。","source":"语法点 · 比较级（le comparatif） · grammar-a1a2.html#comp-adj"},{"id":"q-gram-a2-0047","level":"A2","skill":"grammar","prompt":"Ce vin est ___ que l'autre.（更好）","options":["meilleur","plus bon","mieux","meilleure"],"answer":"meilleur","explain":"bon 的比较级是不规则的 meilleur；plus bon 不是标准法语，mieux 是副词 bien 的比较级（修饰动词），meilleure 是阴性形式，与阳性 vin 不符。","source":"语法点 · 比较级（le comparatif） · grammar-a1a2.html#comp-adj"},{"id":"q-gram-a2-0048","level":"A2","skill":"grammar","prompt":"Il travaille ___ que moi.（更好）","options":["mieux","meilleur","plus bien","meilleure"],"answer":"mieux","explain":"修饰动词 travailler 要用副词比较级 mieux；meilleur 是形容词，用于修饰名词，plus bien 不是标准形式，meilleure 是阴性形容词。","source":"语法点 · 比较级（le comparatif） · grammar-a1a2.html#comp-adj"},{"id":"q-gram-a2-0049","level":"A2","skill":"grammar","prompt":"C'est le ___ restaurant de la ville.","options":["meilleur","mieux","plus bon","meilleure"],"answer":"meilleur","explain":"bon 的最高级是 le meilleur；mieux 是副词，plus bon 不标准，meilleure 是阴性，与阳性名词 restaurant 不符。","source":"语法点 · 最高级（le superlatif） · grammar-a1a2.html#comp-super"},{"id":"q-gram-a2-0050","level":"A2","skill":"grammar","prompt":"Elle est la ___ de la classe.（最聪明）","options":["plus intelligente","plus intelligent","plus intelligentes","le plus intelligente"],"answer":"plus intelligente","explain":"最高级＝定冠词 + plus + 形容词，并与阴性单数主语配合：la plus intelligente；plus intelligent 缺配合，plus intelligentes 是复数，le plus 冠词性数错。","source":"语法点 · 最高级（le superlatif） · grammar-a1a2.html#comp-super"},{"id":"q-gram-a2-0051","level":"A2","skill":"grammar","prompt":"J'habite à Paris ___ cinq ans.","options":["depuis","pendant","il y a","dans"],"answer":"depuis","explain":"depuis 表示从过去持续到现在，常配现在时；pendant 表已结束的一整段时间，il y a 指过去的时间点，dans 指将来的「……之后」。","source":"语法点 · 时间介词（les prépositions de temps） · grammar-a1a2.html#prep-temps"},{"id":"q-gram-a2-0052","level":"A2","skill":"grammar","prompt":"J'ai vécu à Lyon ___ trois ans.","options":["pendant","depuis","il y a","pour"],"answer":"pendant","explain":"已经结束的整段时间用 pendant；depuis 要求动作延续到现在（配现在时），il y a 指过去的时点，pour 表预定要持续的时间（如 partir pour trois ans）。","source":"语法点 · 时间介词（les prépositions de temps） · grammar-a1a2.html#prep-temps"},{"id":"q-gram-a2-0053","level":"A2","skill":"grammar","prompt":"Il est arrivé ___ deux heures.","options":["il y a","dans","depuis","pendant"],"answer":"il y a","explain":"il y a + 时段表示「……以前」；dans 用于将来，depuis 需配现在时表延续，pendant 只表持续时长而不表「以前」。","source":"语法点 · 时间介词（les prépositions de temps） · grammar-a1a2.html#prep-temps"},{"id":"q-gram-a2-0054","level":"A2","skill":"grammar","prompt":"Nous partirons ___ une semaine.","options":["dans","il y a","depuis","pendant"],"answer":"dans","explain":"dans + 时段表示将来的「……之后」：nous partirons dans une semaine；il y a 指向过去，depuis 指向过去的起点并延续到现在，pendant 只表时长。","source":"语法点 · 时间介词（les prépositions de temps） · grammar-a1a2.html#prep-temps"},{"id":"q-gram-a2-0055","level":"A2","skill":"grammar","prompt":"Voici le livre ___ j'ai acheté hier.","options":["que","qui","où","dont"],"answer":"que","explain":"先行词 livre 在从句中作直接宾语，用 que；qui 作主语，où 作时间或地点状语，dont 替代 de + 先行词。","source":"语法点 · 关系代词 qui / que / où（les pronoms relatifs simples） · grammar-a1a2.html#relatifs-a1a2"},{"id":"q-gram-a2-0056","level":"A2","skill":"grammar","prompt":"C'est un ami ___ habite à Nice.","options":["qui","que","dont","où"],"answer":"qui","explain":"先行词 ami 在从句中作主语，用 qui；que 作宾语，dont 替代 de + 先行词，où 作状语。","source":"语法点 · 关系代词 qui / que / où（les pronoms relatifs simples） · grammar-a1a2.html#relatifs-a1a2"},{"id":"q-gram-a2-0057","level":"A2","skill":"grammar","prompt":"La ville ___ je suis né est très petite.","options":["où","que","qui","dont"],"answer":"où","explain":"先行词 ville 表地点，在从句中作地点状语，用 où；从句 je suis né 结构已完整，不需要作宾语的 que，qui 需作主语，dont 替代 de + 先行词。","source":"语法点 · 关系代词 qui / que / où（les pronoms relatifs simples） · grammar-a1a2.html#relatifs-a1a2"},{"id":"q-gram-a2-0058","level":"A2","skill":"grammar","prompt":"Voilà le projet ___ je t'ai parlé.","options":["dont","que","qui","où"],"answer":"dont","explain":"parler de qch 中的 de 由 dont 替代：le projet dont je t'ai parlé；que 会丢掉介词，qui 作主语，où 作状语。","source":"语法点 · 关系代词 qui / que / où（les pronoms relatifs simples） · grammar-a1a2.html#relatifs-a1a2"}],"listening":[{"id":"q-listen-a2-0001","level":"A2","skill":"listening","prompt":"[听力原文] Hier, je suis allé au marché et j'ai acheté des légumes et du fromage. 问题：Qu'est-ce qu'il a acheté ?","options":["Des légumes et du fromage","Des fruits et du pain","Des légumes et du poisson","Du fromage seulement"],"answer":"Des légumes et du fromage","explain":"原文是 légumes et fromage；fruits、pain、poisson 都是同类干扰词，只抓一个词会漏掉另一半信息。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0002","level":"A2","skill":"listening","prompt":"[听力原文] — Pourquoi tu n'es pas venu à la fête ? — J'étais malade, j'avais de la fièvre. 问题：Pourquoi n'est-il pas venu ?","options":["Il était malade","Il travaillait","Il n'aimait pas la fête","Il était en voyage"],"answer":"Il était malade","explain":"j'étais malade, j'avais de la fièvre（发烧）说明原因；工作、旅行、不喜欢都不是原文内容。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0003","level":"A2","skill":"listening","prompt":"[听力原文] Quand j'étais petit, je jouais au tennis tous les mercredis. 问题：Que faisait-il quand il était petit ?","options":["Il jouait au tennis le mercredi","Il jouait au football","Il allait à la piscine","Il travaillait le mercredi"],"answer":"Il jouait au tennis le mercredi","explain":"未完成过去时表过去的习惯：je jouais au tennis tous les mercredis；football、piscine、travailler 都是干扰。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0004","level":"A2","skill":"listening","prompt":"[听力原文] Je pars en vacances la semaine prochaine. Je vais passer huit jours en Bretagne. 问题：Combien de temps va-t-elle rester en Bretagne ?","options":["Huit jours","Une semaine","Quinze jours","Un mois"],"answer":"Huit jours","explain":"原文说 huit jours（八天）；une semaine 是七天，quinze jours 是两周，un mois 是一个月。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0005","level":"A2","skill":"listening","prompt":"[听力原文] Le magasin est fermé le lundi, mais il est ouvert le dimanche matin. 问题：Quand le magasin est-il ouvert ?","options":["Le dimanche matin","Le lundi","Tous les matins","Le dimanche soir"],"answer":"Le dimanche matin","explain":"原文是 ouvert le dimanche matin；lundi 是关门日，tous les matins 与 dimanche soir 都曲解了信息。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0006","level":"A2","skill":"listening","prompt":"[听力原文] — Tu as déjà vu ce film ? — Oui, je l'ai vu deux fois. 问题：Combien de fois a-t-elle vu ce film ?","options":["Deux fois","Une fois","Trois fois","Jamais"],"answer":"Deux fois","explain":"原文 deux fois（两次）；une fois、trois fois 是邻近数字，jamais 与回答 oui 矛盾。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0007","level":"A2","skill":"listening","prompt":"[听力原文] Il pleuvait, donc nous avons décidé de rester à la maison. 问题：Pourquoi sont-ils restés à la maison ?","options":["Parce qu'il pleuvait","Parce qu'ils étaient fatigués","Parce que le musée était fermé","Parce qu'ils n'avaient pas d'argent"],"answer":"Parce qu'il pleuvait","explain":"il pleuvait（未完成过去时背景）是明确原因，donc 引出结果；疲劳、闭馆、没钱都没有出现。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0008","level":"A2","skill":"listening","prompt":"[听力原文] — Qu'est-ce que tu prends au petit déjeuner ? — Un croissant et un café au lait. 问题：Que prend-elle au petit déjeuner ?","options":["Un croissant et un café au lait","Un pain et un thé","Des céréales et un jus","Rien"],"answer":"Un croissant et un café au lait","explain":"原文是 croissant 和 café au lait；thé、céréales、jus 都是同类饮食词干扰。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0009","level":"A2","skill":"listening","prompt":"[听力原文] Je voudrais changer ce pantalon : il est trop petit. 问题：Quel est le problème du pantalon ?","options":["Il est trop petit","Il est trop grand","Il est trop cher","Il est abîmé"],"answer":"Il est trop petit","explain":"顾客说 trop petit（太小）；trop grand 恰好相反，cher 和 abîmé 在原文没有出现。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0010","level":"A2","skill":"listening","prompt":"[听力原文] La poste se trouve en face de la pharmacie, à côté de la boulangerie. 问题：Où est la poste ?","options":["En face de la pharmacie","Derrière la pharmacie","Dans la boulangerie","À côté de la banque"],"answer":"En face de la pharmacie","explain":"en face de la pharmacie（在药店对面）；à côté de la boulangerie 是另一个参照物，banque 是替换干扰。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0011","level":"A2","skill":"listening","prompt":"[听力原文] Mon frère a vingt-cinq ans et il est étudiant en informatique. 问题：Que fait son frère ?","options":["Il est étudiant","Il est professeur","Il est ingénieur","Il est lycéen"],"answer":"Il est étudiant","explain":"原文说 il est étudiant en informatique；ingénieur（工程师）是毕业后的职业设想，lycéen 是高中生，混淆了两个阶段。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0012","level":"A2","skill":"listening","prompt":"[听力原文] — Vous pouvez me rappeler demain matin ? — Oui, je vous appelle à neuf heures. 问题：Quand va-t-il rappeler ?","options":["Demain matin à neuf heures","Ce soir","Demain après-midi","À dix heures"],"answer":"Demain matin à neuf heures","explain":"约定是 demain matin 加 neuf heures；ce soir、après-midi 时间不符，dix heures 是数字干扰。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0013","level":"A2","skill":"listening","prompt":"[听力原文] J'ai fait mes études à Toulouse, puis j'ai travaillé à Marseille pendant trois ans. 问题：Où a-t-il travaillé ?","options":["À Marseille","À Toulouse","À Paris","À Nantes"],"answer":"À Marseille","explain":"travailler 对应 Marseille，Toulouse 是求学城市；Paris、Nantes 都没有出现。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0014","level":"A2","skill":"listening","prompt":"[听力原文] Attention, le train part à quatorze heures trente, voie cinq. 问题：Sur quelle voie part le train ?","options":["Voie cinq","Voie quinze","Voie neuf","Voie deux"],"answer":"Voie cinq","explain":"voie cinq（5 号站台）；quinze [kɛ̃z] 与 cinq [sɛ̃k] 音近，neuf 和 deux 是数字干扰。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0015","level":"A2","skill":"listening","prompt":"[听力原文] Je préfère le train à l'avion, parce que c'est plus confortable et moins cher. 问题：Pourquoi préfère-t-elle le train ?","options":["Parce que c'est plus confortable et moins cher","Parce que c'est plus rapide","Parce que l'avion est dangereux","Parce qu'elle a peur de l'avion"],"answer":"Parce que c'est plus confortable et moins cher","explain":"原因是比较级 plus confortable 和 moins cher；plus rapide 恰好相反（飞机更快），危险和害怕都是没提到的推测。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0016","level":"A2","skill":"listening","prompt":"[听力原文] — Tu as téléphoné à tes parents ? — Oui, je leur ai parlé hier soir. 问题：À qui a-t-elle parlé ?","options":["À ses parents","À ses amis","À son frère","À son professeur"],"answer":"À ses parents","explain":"à tes parents 与回答中的 leur 对应；其余人物都没有出现在原文。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0017","level":"A2","skill":"listening","prompt":"[听力原文] Il fait très chaud aujourd'hui : il fait trente-deux degrés. 问题：Quelle température fait-il ?","options":["32 degrés","22 degrés","30 degrés","42 degrés"],"answer":"32 degrés","explain":"trente-deux degrés（32 度）；vingt-deux 是 22，trente 是 30，quarante-deux 是 42，关键是抓住词尾 deux。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"},{"id":"q-listen-a2-0018","level":"A2","skill":"listening","prompt":"[听力原文] Je cherche un appartement près de l'université, pas trop cher, avec deux chambres. 问题：Qu'est-ce qu'elle cherche ?","options":["Un appartement de deux chambres pas trop cher","Une chambre à l'université","Une maison avec jardin","Un studio très cher"],"answer":"Un appartement de deux chambres pas trop cher","explain":"条件包含三项信息：près de l'université、pas trop cher、deux chambres；studio、maison、chambre seule 都改变了原意。","source":"听力 · A2 短对话（compréhension orale A2 · DELF）"}],"reading":[{"id":"q-read-a2-0001","level":"A2","skill":"reading","prompt":"[阅读] Hier, je suis allée au marché. J'ai acheté des fraises et du fromage. Ensuite, je suis rentrée à la maison parce qu'il commençait à pleuvoir. 问题：Pourquoi est-elle rentrée à la maison ?","options":["Parce qu'il commençait à pleuvoir","Parce qu'elle était fatiguée","Parce que le marché était fermé","Parce qu'elle avait oublié son argent"],"answer":"Parce qu'il commençait à pleuvoir","explain":"原因从句是 parce qu'il commençait à pleuvoir（未完成过去时表刚开始下雨的背景）；疲劳、闭市、忘带钱都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0002","level":"A2","skill":"reading","prompt":"[阅读] Nous avons décidé de partir en Bretagne en juillet. Nous réserverons un gîte près de la mer et nous visiterons les petits ports. 问题：Que feront-ils en Bretagne ?","options":["Ils réserveront un gîte et visiteront les ports","Ils achèteront une maison","Ils iront à la montagne","Ils travailleront"],"answer":"Ils réserveront un gîte et visiteront les ports","explain":"将来时给出计划：réserver un gîte 和 visiter les ports；买房子、去山区、工作都与原文不符。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0003","level":"A2","skill":"reading","prompt":"[阅读] Le mois dernier, j'ai commencé un nouveau travail. Le salaire est correct, mais les horaires sont difficiles : je finis à 22 heures. 问题：Quel est le problème de ce nouveau travail ?","options":["Les horaires","Le salaire","Les collègues","La distance"],"answer":"Les horaires","explain":"转折词 mais 之后才是问题：horaires difficiles（22 点下班）；salaire 是「还行」的正面信息，同事和距离没提。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0004","level":"A2","skill":"reading","prompt":"[阅读] Je voudrais m'inscrire à un cours de cuisine. Est-ce qu'il y a encore des places le mardi soir ? 问题：Que demande cette personne ?","options":["Si le cours du mardi soir a encore des places","Le prix du cours","L'adresse de l'école","La durée du cours"],"answer":"Si le cours du mardi soir a encore des places","explain":"询问的是 Est-ce qu'il y a encore des places le mardi soir；价格、地址、时长都不是问题内容。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0005","level":"A2","skill":"reading","prompt":"[阅读] La bibliothèque est fermée le lundi matin, mais ouverte le lundi après-midi de 14 h à 18 h. 问题：Quand la bibliothèque est-elle ouverte le lundi ?","options":["De 14 h à 18 h","Le matin","Toute la journée","Elle est fermée toute la journée"],"answer":"De 14 h à 18 h","explain":"周一下午开放 14 h-18 h；上午关门，「开一整天」和「全天关门」都不对。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0006","level":"A2","skill":"reading","prompt":"[阅读] J'ai fait mes études à Lille, puis j'ai trouvé un emploi à Nantes. J'y habite depuis trois ans. 问题：Où habite-t-il maintenant ?","options":["À Nantes","À Lille","À Paris","Dans deux villes"],"answer":"À Nantes","explain":"j'y habite depuis trois ans 中的 y 指 Nantes；Lille 是求学地（过去），Paris 没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0007","level":"A2","skill":"reading","prompt":"[阅读] Les soldes commencent mercredi. Les prix baissent de 30 % à 50 % dans tous les magasins du centre. 问题：Quelle est la réduction annoncée ?","options":["De 30 % à 50 %","50 % partout","30 % seulement","70 %"],"answer":"De 30 % à 50 %","explain":"de 30 % à 50 % 是一个区间；「一律 50%」「只减 30%」都曲解了区间，70% 是把两个数字相加的错误。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0008","level":"A2","skill":"reading","prompt":"[阅读] Je suis désolé, je ne peux pas venir samedi : je dois accompagner ma fille à un tournoi de judo. 问题：Pourquoi ne peut-il pas venir samedi ?","options":["Il accompagne sa fille à un tournoi","Il travaille","Il est malade","Il part en vacances"],"answer":"Il accompagne sa fille à un tournoi","explain":"原因明确是 accompagner sa fille à un tournoi de judo；其他三项都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0009","level":"A2","skill":"reading","prompt":"[阅读] Pour aller à la gare, prenez la ligne 3 du métro et descendez à la station « Gare centrale ». Le trajet dure environ vingt minutes. 问题：Combien de temps dure le trajet ?","options":["Environ vingt minutes","Environ trente minutes","Environ dix minutes","Deux heures"],"answer":"Environ vingt minutes","explain":"le trajet dure environ vingt minutes；trente、dix 是邻近数字，deux heures 是把 vingt 与 heures 混读的错误。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0010","level":"A2","skill":"reading","prompt":"[阅读] Quand j'étais enfant, je passais toutes mes vacances chez mes grands-parents, dans un petit village. 问题：Où passait-il ses vacances quand il était enfant ?","options":["Chez ses grands-parents","À l'hôtel","Chez ses cousins","À la mer"],"answer":"Chez ses grands-parents","explain":"未完成过去时表过去的习惯：passais toutes mes vacances chez mes grands-parents；其他地点都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0011","level":"A2","skill":"reading","prompt":"[阅读] Mon médecin m'a conseillé de me reposer et de boire beaucoup d'eau. Il m'a donné une ordonnance. 问题：Que lui a conseillé le médecin ?","options":["De se reposer et de boire de l'eau","De faire du sport","De manger moins","De prendre des vitamines"],"answer":"De se reposer et de boire de l'eau","explain":"conseiller de + 不定式给出两条建议：休息与多喝水；运动、少吃、维生素都不在医嘱里。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0012","level":"A2","skill":"reading","prompt":"[阅读] Le festival a lieu du 5 au 12 août. Les concerts commencent à 20 h 30 et l'entrée est gratuite pour les moins de 18 ans. 问题：Qui entre gratuitement ?","options":["Les moins de 18 ans","Tous les habitants","Les étudiants","Les personnes âgées"],"answer":"Les moins de 18 ans","explain":"免费条件是 les moins de 18 ans（18 岁以下）；学生和老人都不在免费范围内。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0013","level":"A2","skill":"reading","prompt":"[阅读] Je cherche une colocation près de l'université. Je suis calme, non-fumeur et j'aime cuisiner. 问题：Quels sont ses atouts pour une colocation ?","options":["Calme, non-fumeur et bon cuisinier","Bruyant et fumeur","Souvent absent","Très riche"],"answer":"Calme, non-fumeur et bon cuisinier","explain":"三项自我描述都是合租加分项；其余选项与原文相反或没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0014","level":"A2","skill":"reading","prompt":"[阅读] L'année dernière, nous sommes allés en Italie en voiture. Le voyage a duré deux jours et nous avons visité Florence et Venise. 问题：Comment ont-ils voyagé ?","options":["En voiture","En train","En avion","En bus"],"answer":"En voiture","explain":"原文是 en voiture；火车、飞机、大巴都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0015","level":"A2","skill":"reading","prompt":"[阅读] Attention : à partir du 1er octobre, le magasin sera ouvert jusqu'à 21 heures le vendredi. 问题：Qu'est-ce qui change en octobre ?","options":["La fermeture plus tardive le vendredi","L'ouverture le dimanche","La fermeture définitive du magasin","Les prix"],"answer":"La fermeture plus tardive le vendredi","explain":"ouvert jusqu'à 21 heures le vendredi 指周五延长营业；周日营业、关店、价格都没有提到。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0016","level":"A2","skill":"reading","prompt":"[阅读] J'ai reçu ton message. Je te réponds rapidement : je suis d'accord avec ton idée, mais il faut fixer une date. 问题：Quelle est sa réponse ?","options":["Il est d'accord mais veut fixer une date","Il refuse l'idée","Il n'a pas reçu le message","Il propose une autre idée"],"answer":"Il est d'accord mais veut fixer une date","explain":"d'accord avec ton idée 加 mais il faut fixer une date；拒绝、没收到、另有想法都与原文不符。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0017","level":"A2","skill":"reading","prompt":"[阅读] Ce quartier est très pratique : la station de métro est à cinq minutes à pied et il y a un supermarché juste en face. 问题：Pourquoi ce quartier est-il pratique ?","options":["Le métro est proche et il y a un supermarché","Les loyers sont bas","Les écoles sont excellentes","C'est calme le soir"],"answer":"Le métro est proche et il y a un supermarché","explain":"交通近与有超市是原文给出的两个便利理由；房租、学校、安静都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"},{"id":"q-read-a2-0018","level":"A2","skill":"reading","prompt":"[阅读] Je suis arrivé en retard à cause d'une grève des transports. Heureusement, la réunion n'avait pas encore commencé. 问题：Pourquoi est-il arrivé en retard ?","options":["À cause d'une grève","Parce qu'il s'est levé tard","Parce qu'il a raté le bus","À cause des embouteillages"],"answer":"À cause d'une grève","explain":"à cause d'une grève des transports 是明确原因；起晚、误车、堵车都没有出现。","source":"阅读 · A2 邮件与广告（compréhension écrite A2 · DELF）"}],"writing":[{"id":"q-writ-a2-0001","level":"A2","skill":"writing","prompt":"写作自评（叙述昨天），选出时态配合正确的一句：","options":["Hier, il pleuvait, donc nous sommes restés à la maison.","Hier, il a plu, donc nous restions à la maison.","Hier, il pleuvait, donc nous restions à la maison.","Hier, il pleuvait, donc nous avons resté à la maison."],"answer":"Hier, il pleuvait, donc nous sommes restés à la maison.","explain":"背景用未完成过去时 pleuvait，被引出的事件用复合过去时 sommes restés；restions 缺事件推进，avons resté 助动词错（rester 用 être）。","source":"写作自评 · A2 日记（production écrite A2）"},{"id":"q-writ-a2-0002","level":"A2","skill":"writing","prompt":"写作自评（通知地址变更），选出正确的一句：","options":["Je vous écris pour vous informer de mon changement d'adresse.","Je vous écris pour vous informer mon changement d'adresse.","Je vous écris pour informer vous de mon changement d'adresse.","Je vous écris pour vous informez de mon changement d'adresse."],"answer":"Je vous écris pour vous informer de mon changement d'adresse.","explain":"informer qqn de qch → vous informer de…；informez 是变位形式不能跟在 pour 后，informer vous 词序错误。","source":"写作自评 · A2 正式通知（production écrite A2）"},{"id":"q-writ-a2-0003","level":"A2","skill":"writing","prompt":"写作自评（条件句），选出正确的一句：","options":["Si j'avais le temps, je viendrais avec vous.","Si j'aurais le temps, je viendrais avec vous.","Si j'avais le temps, je viendrai avec vous.","Si j'ai le temps, je viendrais avec vous."],"answer":"Si j'avais le temps, je viendrais avec vous.","explain":"si 从句用未完成过去时，主句用条件式现在时；si + 条件式（j'aurais）是中国学生最常犯的错误，viendrai 与从句时态不搭。","source":"写作自评 · A2 假设（production écrite A2）"},{"id":"q-writ-a2-0004","level":"A2","skill":"writing","prompt":"写作自评（邮件请求），选出正确的一句：","options":["Merci de me répondre avant vendredi.","Merci de me réponds avant vendredi.","Merci de répondre-moi avant vendredi.","Merci me répondre avant vendredi."],"answer":"Merci de me répondre avant vendredi.","explain":"merci de + 不定式；réponds 是变位形式，répondre-moi 在不定式中代词必须前置（me répondre），漏 de 则结构不成立。","source":"写作自评 · A2 邮件（production écrite A2）"},{"id":"q-writ-a2-0005","level":"A2","skill":"writing","prompt":"写作自评（决定），选出正确的一句：","options":["Nous avons décidé de partir tôt pour éviter les embouteillages.","Nous avons décidé partir tôt pour éviter les embouteillages.","Nous avons décidé de partir tôt pour éviter des embouteillages.","Nous avons décidé de partir tôt pour éviter les embouteillage."],"answer":"Nous avons décidé de partir tôt pour éviter les embouteillages.","explain":"décider de + 不定式（漏 de 是高频错）；泛指一类事物用定冠词 les embouteillages，且名词要带复数 -s。","source":"写作自评 · A2 计划（production écrite A2）"},{"id":"q-writ-a2-0006","level":"A2","skill":"writing","prompt":"写作自评（比较），选出正确的一句：","options":["Ce restaurant est meilleur que celui d'à côté.","Ce restaurant est plus bon que celui d'à côté.","Ce restaurant est mieux que celui d'à côté.","Ce restaurant est meilleur que celui à côté."],"answer":"Ce restaurant est meilleur que celui d'à côté.","explain":"bon 的比较级是不规则的 meilleur；plus bon 不标准，mieux 是副词 bien 的比较级，celui d'à côté 中 de 不能省略。","source":"写作自评 · A2 比较（production écrite A2）"},{"id":"q-writ-a2-0007","level":"A2","skill":"writing","prompt":"写作自评（必要性），选出正确的一句：","options":["Il faut que je parte maintenant, sinon je vais être en retard.","Il faut que je pars maintenant, sinon je vais être en retard.","Il faut que je partie maintenant, sinon je vais être en retard.","Il faut que je partir maintenant, sinon je vais être en retard."],"answer":"Il faut que je parte maintenant, sinon je vais être en retard.","explain":"il faut que + 虚拟式（parte）；pars 是直陈式，partie 和 partir 都不是虚拟式形式。","source":"写作自评 · A2 说明（production écrite A2）"},{"id":"q-writ-a2-0008","level":"A2","skill":"writing","prompt":"写作自评（时间顺序），选出正确的一句：","options":["Après avoir fini mes études, j'ai travaillé à Pékin.","Après j'ai fini mes études, j'ai travaillé à Pékin.","Après finir mes études, j'ai travaillé à Pékin.","Après être fini mes études, j'ai travaillé à Pékin."],"answer":"Après avoir fini mes études, j'ai travaillé à Pékin.","explain":"après + 复合不定式（après avoir fini）表先时性；après 后接从句必须用 après que，après finir 结构不成立。","source":"写作自评 · A2 经历（production écrite A2）"},{"id":"q-writ-a2-0009","level":"A2","skill":"writing","prompt":"写作自评（间接疑问），选出正确的一句：","options":["Je voudrais savoir si le prix comprend les charges.","Je voudrais savoir que le prix comprend les charges.","Je voudrais savoir est-ce que le prix comprend les charges.","Je voudrais savoir si le prix comprend-t-il les charges."],"answer":"Je voudrais savoir si le prix comprend les charges.","explain":"间接一般疑问用 si + 陈述语序，不用倒装也不用 est-ce que；que 只能引导陈述内容，est-ce que 与 si 不能叠用。","source":"写作自评 · A2 咨询（production écrite A2）"},{"id":"q-writ-a2-0010","level":"A2","skill":"writing","prompt":"写作自评（转述请求），选出正确的一句：","options":["Elle m'a demandé de l'aider à remplir le formulaire.","Elle m'a demandé de l'aider de remplir le formulaire.","Elle m'a demandé à l'aider à remplir le formulaire.","Elle m'a demandé de lui aider à remplir le formulaire."],"answer":"Elle m'a demandé de l'aider à remplir le formulaire.","explain":"demander à qqn de faire qch；demander à l'aider 搭配错误，lui aider 也错（aider 直接接宾语 l'aider）。","source":"写作自评 · A2 转述（production écrite A2）"},{"id":"q-writ-a2-0011","level":"A2","skill":"writing","prompt":"写作自评（比较级叠用），选出正确的一句：","options":["Plus je lis, mieux j'écris.","Plus je lis, plus bien j'écris.","Plus je lis, meilleur j'écris.","Plus je lis, plus j'écris mieux."],"answer":"Plus je lis, mieux j'écris.","explain":"比较级叠用 plus… mieux…，修饰动词 écrire 要用副词 mieux；plus bien 不标准，meilleur 是形容词，不能修饰动词。","source":"写作自评 · A2 学习心得（production écrite A2）"},{"id":"q-writ-a2-0012","level":"A2","skill":"writing","prompt":"写作自评（准备考试），选出正确的一句：","options":["Il est important de bien se préparer avant l'examen.","Il est important bien se préparer avant l'examen.","Il est important de bien préparer avant l'examen.","Il est important de bien que se préparer avant l'examen."],"answer":"Il est important de bien se préparer avant l'examen.","explain":"无人称结构 il est important de + 不定式；漏 de 不成立，préparer 缺自反代词会改变意思（变成「准备某物」），que 与不定式叠用错误。","source":"写作自评 · A2 学习计划（production écrite A2）"},{"id":"q-writ-a2-0013","level":"A2","skill":"writing","prompt":"写作自评（正在做某事），选出正确的一句：","options":["Je suis en train de préparer le dîner.","Je suis en train préparer le dîner.","Je suis en train de prépare le dîner.","Je suis en train que je prépare le dîner."],"answer":"Je suis en train de préparer le dîner.","explain":"être en train de + 不定式；漏 de、用变位形式 prépare、加 que 从句都不成立。","source":"写作自评 · A2 日常（production écrite A2）"},{"id":"q-writ-a2-0014","level":"A2","skill":"writing","prompt":"写作自评（提醒），选出正确的一句：","options":["Avant de partir, pense à éteindre la lumière.","Avant de partir, pense d'éteindre la lumière.","Avant partir, pense à éteindre la lumière.","Avant de partir, penses à éteindre la lumière."],"answer":"Avant de partir, pense à éteindre la lumière.","explain":"penser à + 不定式；de 是英语式误搭，avant 作介词必须带 de，命令式 tu 形式的 -er 动词不带 -s（pense）。","source":"写作自评 · A2 提醒（production écrite A2）"},{"id":"q-writ-a2-0015","level":"A2","skill":"writing","prompt":"写作自评（相识时间），选出正确的一句：","options":["Nous nous sommes rencontrés il y a trois ans.","Nous nous sommes rencontrés pendant trois ans.","Nous nous sommes rencontrés depuis trois ans.","Nous nous rencontrons il y a trois ans."],"answer":"Nous nous sommes rencontrés il y a trois ans.","explain":"il y a + 时段表「……以前」，rencontrer 用 être 且代词式相互动词过去分词加 -s；pendant 表持续时长（见面三年不通），depuis 要与现在时搭配。","source":"写作自评 · A2 经历（production écrite A2）"},{"id":"q-writ-a2-0016","level":"A2","skill":"writing","prompt":"写作自评（期待见面），选出正确的一句：","options":["J'ai hâte de te voir à Paris le mois prochain.","J'ai hâte que te voir à Paris le mois prochain.","J'ai hâte de te vois à Paris le mois prochain.","J'ai hâte te voir à Paris le mois prochain."],"answer":"J'ai hâte de te voir à Paris le mois prochain.","explain":"avoir hâte de + 不定式；que 与不定式叠用错，vois 是变位形式，漏 de 结构不成立。","source":"写作自评 · A2 短信（production écrite A2）"}],"speaking":[{"id":"q-speak-a2-0001","level":"A2","skill":"speaking","prompt":"口语自评（请求帮助），选出最得体的一句：","options":["Pourriez-vous m'aider, s'il vous plaît ?","Pouvez-vous m'aidez, s'il vous plaît ?","Pourriez-vous m'aider, s'il te plaît ?","Pourriez-vous que m'aider ?"],"answer":"Pourriez-vous m'aider, s'il vous plaît ?","explain":"条件式 Pourriez-vous 表礼貌且后接不定式 m'aider；m'aidez 是变位形式，s'il te plaît 与 vous 冲突，que 与不定式叠用错误。","source":"口语自评 · A2 请求帮助（production orale A2）"},{"id":"q-speak-a2-0002","level":"A2","skill":"speaking","prompt":"口语自评（预约医生），选出正确的一句：","options":["Je voudrais prendre rendez-vous avec le médecin pour jeudi.","Je voudrais prendre rendez-vous avec le médecin à jeudi.","Je voudrais prendre rendez-vous le médecin pour jeudi.","Je voudrais que prendre rendez-vous avec le médecin pour jeudi."],"answer":"Je voudrais prendre rendez-vous avec le médecin pour jeudi.","explain":"prendre rendez-vous avec qqn 用 avec，时间用 pour jeudi；à jeudi 是介词误搭，漏 avec 不成立，que 与不定式叠用错误。","source":"口语自评 · A2 预约（production orale A2）"},{"id":"q-speak-a2-0003","level":"A2","skill":"speaking","prompt":"口语自评（委婉拒绝邀请），选出最得体的一句：","options":["Merci beaucoup pour l'invitation, mais je ne suis malheureusement pas libre ce soir-là.","Non.","Je ne viens pas.","Peut-être non."],"answer":"Merci beaucoup pour l'invitation, mais je ne suis malheureusement pas libre ce soir-là.","explain":"委婉拒绝要先致谢再说明原因；只说 Non、直接说 Je ne viens pas 都过于生硬，Peut-être non 既模糊也不合法语表达习惯。","source":"口语自评 · A2 拒绝（production orale A2）"},{"id":"q-speak-a2-0004","level":"A2","skill":"speaking","prompt":"口语自评（询问价格），选出正确的一句：","options":["Combien ça coûte, s'il vous plaît ?","Combien ça coûte de ?","Combien coûte ça le prix ?","Combien le prix ?"],"answer":"Combien ça coûte, s'il vous plaît ?","explain":"combien ça coûte 已是完整问句；de 是多余介词，coûte ça le prix 语义重复，Combien le prix 缺动词。","source":"口语自评 · A2 购物（production orale A2）"},{"id":"q-speak-a2-0005","level":"A2","skill":"speaking","prompt":"口语自评（请店员推荐），选出正确的一句：","options":["Qu'est-ce que vous me conseillez ?","Qu'est-ce que vous me conseillez de ?","Que vous me conseillez ?","Quoi que vous me conseillez ?"],"answer":"Qu'est-ce que vous me conseillez ?","explain":"特殊疑问可用 est-ce que 结构（也可倒装 Que me conseillez-vous ?）；de 多余，第三句缺疑问结构，quoi que 是连词「无论什么」不能用来提问。","source":"口语自评 · A2 餐厅（production orale A2）"},{"id":"q-speak-a2-0006","level":"A2","skill":"speaking","prompt":"口语自评（表达不确定），选出正确的一句：","options":["Je ne suis pas sûr de pouvoir venir.","Je ne suis pas sûr que pouvoir venir.","Je ne suis pas sûr venir.","Je ne suis sûr pas de pouvoir venir."],"answer":"Je ne suis pas sûr de pouvoir venir.","explain":"主语一致时 être sûr de + 不定式；que 后面必须接从句，漏 de 不成立，否定词要夹住变位动词（je ne suis pas sûr）。","source":"口语自评 · A2 表达态度（production orale A2）"},{"id":"q-speak-a2-0007","level":"A2","skill":"speaking","prompt":"口语自评（电话确认对方身份），选出正确的一句：","options":["Bonjour, je suis bien chez M. Martin ?","Bonjour, je suis bien à M. Martin ?","Bonjour, je suis chez bien M. Martin ?","Bonjour, je suis bien dans M. Martin ?"],"answer":"Bonjour, je suis bien chez M. Martin ?","explain":"chez 只接人，表示「在某人处」；à 和 dans 都不能接人，副词 bien 不能插在 chez 前面。","source":"口语自评 · A2 电话（production orale A2）"},{"id":"q-speak-a2-0008","level":"A2","skill":"speaking","prompt":"口语自评（请对方重复），选出正确的一句：","options":["Vous pouvez répéter, s'il vous plaît ?","Vous pouvez répétez, s'il vous plaît ?","Vous pouvez répéter, s'il te plaît ?","Vous répétez, s'il vous plaît ?"],"answer":"Vous pouvez répéter, s'il vous plaît ?","explain":"pouvoir 后接不定式 répéter；répétez 是变位形式，s'il te plaît 与 vous 不一致，最后一句语气生硬且缺少请求结构。","source":"口语自评 · A2 沟通策略（production orale A2）"},{"id":"q-speak-a2-0009","level":"A2","skill":"speaking","prompt":"口语自评（约定时间），选出正确的一句：","options":["Ça vous va si on se retrouve à 18 heures devant la gare ?","Ça vous va que on se retrouve à 18 heures devant la gare ?","Ça vous va si on se retrouvons à 18 heures devant la gare ?","Ça vous va si on se retrouve à 18 heures devant gare ?"],"answer":"Ça vous va si on se retrouve à 18 heures devant la gare ?","explain":"假设条件用 si，on 后动词用第三人称单数 se retrouve，地点名词前要有冠词 la gare；que 不能引导条件。","source":"口语自评 · A2 约会（production orale A2）"},{"id":"q-speak-a2-0010","level":"A2","skill":"speaking","prompt":"口语自评（表达同意），选出正确的一句：","options":["Je suis tout à fait d'accord avec vous.","Je suis tout à fait d'accord à vous.","Je suis tout à fait d'accord de vous.","Je suis tout à fait accord avec vous."],"answer":"Je suis tout à fait d'accord avec vous.","explain":"être d'accord avec qqn 是固定搭配；à 和 de 都是误搭，d'accord 中的 de 不能省略。","source":"口语自评 · A2 表达观点（production orale A2）"},{"id":"q-speak-a2-0011","level":"A2","skill":"speaking","prompt":"口语自评（询问看法），选出正确的一句：","options":["Qu'est-ce que vous en pensez ?","Qu'est-ce que vous pensez de ?","Qu'est-ce que vous le pensez ?","Qu'est-ce que vous en pensez de ?"],"answer":"Qu'est-ce que vous en pensez ?","explain":"penser de qch 询问看法，代词 en 要前置：qu'est-ce que vous en pensez ?；只留 de 缺宾语，用 le（直接宾语）不搭配，en 与 de 叠用也错。","source":"口语自评 · A2 表达观点（production orale A2）"},{"id":"q-speak-a2-0012","level":"A2","skill":"speaking","prompt":"口语自评（请求借用），选出正确的一句：","options":["Est-ce que je peux emprunter votre stylo ?","Est-ce que je peux emprunter à votre stylo ?","Est-ce que je peux que emprunter votre stylo ?","Est-ce que je peux emprunter de votre stylo ?"],"answer":"Est-ce que je peux emprunter votre stylo ?","explain":"emprunter qch à qqn（向某人借入），物品直接作宾语；à/de 是多余介词，que 与不定式叠用错误。","source":"口语自评 · A2 求助（production orale A2）"},{"id":"q-speak-a2-0013","level":"A2","skill":"speaking","prompt":"口语自评（致谢告别），选出正确的一句：","options":["Merci pour votre aide, bonne continuation !","Merci pour votre aide, bon continuation !","Merci pour votre aide, bonne continuer !","Merci votre aide, bonne continuation !"],"answer":"Merci pour votre aide, bonne continuation !","explain":"merci pour + 名词；continuation 是阴性名词，用 bonne；继续是动词，不能用动词形式作名词；merci 后必须接 pour 或 de。","source":"口语自评 · A2 告别（production orale A2）"},{"id":"q-speak-a2-0014","level":"A2","skill":"speaking","prompt":"口语自评（要求换货），选出正确的一句：","options":["Je voudrais échanger cet article, il ne me va pas.","Je voudrais échanger cet article, il ne me vais pas.","Je voudrais échanger cet article, il ne va pas moi.","Je voudrais échanger cet article, il ne m'en va pas."],"answer":"Je voudrais échanger cet article, il ne me va pas.","explain":"aller à qqn（合身）用间接宾语代词 me，主语 il 与 va 配合；vais 是 je 的形式，代词不能放在动词后，en 在此没有替代对象。","source":"口语自评 · A2 购物（production orale A2）"},{"id":"q-speak-a2-0015","level":"A2","skill":"speaking","prompt":"口语自评（打扰别人），选出正确的一句：","options":["Excusez-moi de vous déranger, auriez-vous un instant ?","Excusez-moi vous déranger, auriez-vous un instant ?","Excusez-moi à vous déranger, auriez-vous un instant ?","Excusez-moi de déranger vous, auriez-vous un instant ?"],"answer":"Excusez-moi de vous déranger, auriez-vous un instant ?","explain":"excuser qqn de + 不定式，代词 vous 要放在不定式前；漏 de、用 à、把代词放在不定式后都是错误。","source":"口语自评 · A2 礼貌用语（production orale A2）"},{"id":"q-speak-a2-0016","level":"A2","skill":"speaking","prompt":"口语自评（正式道别），选出正确的一句：","options":["Au revoir, Madame, et merci encore.","Au revoir, Madame, et merci beaucoup encore.","Au revoir, Madame, et merci encore de.","Au revoir, Madame, et encore merci de vous."],"answer":"Au revoir, Madame, et merci encore.","explain":"merci encore 是自然搭配；beaucoup 与 encore 叠用不地道，句末孤立的 de 是残句，merci de vous 结构不成立（应 merci à vous）。","source":"口语自评 · A2 告别（production orale A2）"}]}}.A2;
